public class Demo {
    public static void main(String[] args) {
        // 1. Cree un Runnable qui affiche "Tache terminee"
        // 2. Cree un Thread avec ce Runnable
        // 3. Demarre le thread (attention a start() et non run())
    }
}

solution:
public class Demo {
    public static void main(String[] args) {
        Runnable tache = () -> System.out.println("Tache terminee");
        Thread t = new Thread(tache);
        t.start();
    }
}
